&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les &#233;coles de magie&lt;a class=&quot;headeranchor&quot; id=&quot;Les_&#233;coles_de_magie_0&quot; href=&quot;#Les_&#233;coles_de_magie_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;coles-De-Magie.html&quot; title=&quot;Les &#233;coles de magie du magicien&quot;&gt;pr&#233;sentation&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Abjuration-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Abjuration&quot;&gt;Abjuration&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Air-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de l&amp;#39;Air&quot;&gt;Air&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bois-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du Bois&quot;&gt;Bois&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Divination-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de Divination&quot;&gt;Divination&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Eau-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de l&amp;#39;Eau&quot;&gt;Eau&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enchantement-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Enchantement&quot;&gt;Enchantement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vocation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;&#201;vocation&quot;&gt;&#201;vocation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feu-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du Feu&quot;&gt;Feu&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Illusion-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Illusion&quot;&gt;Illusion&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invocation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole d&amp;#39;Invocation&quot;&gt;Invocation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tal-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du M&#233;tal&quot;&gt;M&#233;tal&lt;/a&gt; (UM)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;ant-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire du N&#233;ant&quot;&gt;N&#233;ant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;cromancie-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terre-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole &#233;l&#233;mentaire de la Terre&quot;&gt;Terre&lt;/a&gt; (APG)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transmutation-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole de Transmutation&quot;&gt;Transmutation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Universelle-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole Universelle&quot;&gt;&#201;cole universelle&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Plus d&#39;information sur les sorts de cette &#233;cole &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#INVOCATION&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;ici&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;L’invocateur &#233;tudie principalement les sorts qui lui permettent de conjurer des monstres et de les soumettre &#224; sa volont&#233;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ma&#238;trise des invocations (Sur).&lt;/b&gt; Chaque fois que l’invocateur lance un sort d’invocation (convocation), la dur&#233;e de celui-ci augmente d’un nombre de rounds &#233;gal &#224; la moiti&#233; de son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; (au minimum 1). Cette dur&#233;e suppl&#233;mentaire n&#39;est pas doubl&#233;e par le don &lt;a class=&quot;pagelink&quot; href=&quot;Extension-De-Dur&#233;e.html&quot; title=&quot;Extension de dur&#233;e&quot;&gt;Extension de Dur&#233;e&lt;/a&gt;.  Au niveau 20, l’invocateur peut changer la dur&#233;e de n’importe quel sort de convocation de monstres en &#171; permanente &#187;. Il ne peut cependant  maintenir qu’un seul sort de convocation de monstres permanent &#224; la fois. S’il lance un autre sort de convocation de monstres en d&#233;cidant de le rendre permanent, le sort pr&#233;c&#233;dent prend imm&#233;diatement fin.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Fl&#233;chette d’acide (Mag).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, l’invocateur peut envoyer une fl&#233;chette d’acide sur un ennemi distant de 9 m (6 cases) ou moins en r&#233;ussissant une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;attaque de contact&quot;&gt;attaque de contact&lt;/a&gt; &#224; distance. La fl&#233;chette d’acide inflige 1d6 points de d&#233;g&#226;ts d’acide + 1 point par deux niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Chaque jour, l’invocateur peut utiliser ce pouvoir un nombre de fois &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;. Cette attaque ignore la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pas interdimensionnels (Mag).&lt;/b&gt; Ce pouvoir permet &#224; un invocateur de niveau 8 de se t&#233;l&#233;porter chaque jour sur une distance totale de 9 m (6 cases) par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;Niveau de lanceur de sorts&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;. Chaque utilisation de ce pouvoir n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; et doit correspondre &#224; une distance exprimable sous la forme d’un multiple de 1,50 m (1 case). Le d&#233;placement induit par ce pouvoir ne provoque pas d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaque d&#39;opportunit&#233;&lt;/a&gt;. L’invocateur peut emmener d’autres cr&#233;atures avec lui (pour autant qu’elles soient d’accord) mais il doit alors d&#233;compter plusieurs fois la distance parcourue de son quota journalier (une fois pour lui et une fois de plus pour chaque personne qui l’accompagne).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Champs d&#39;&#233;tude magiques&lt;a class=&quot;headeranchor&quot; id=&quot;Champs_d&#233;tude_magiques_0&quot; href=&quot;#Champs_d&#233;tude_magiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt; qui se sp&#233;cialisent dans une &#233;cole de magie peuvent choisir de restreindre davantage encore leur domaine d’&#233;tude. Les &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt; qui choisissent un champ d’&#233;tude magique conservent les sorts en bonus de leur &#233;cole de sp&#233;cialisation et doivent toujours s&#233;lectionner deux &#233;coles oppos&#233;es mais certains de leurs pouvoirs d’&#233;cole de magie sont modifi&#233;s ou remplac&#233;s. Ils doivent accepter toutes les modifications impos&#233;es par leur champ d’&#233;tude. Une fois un champ d’&#233;tude choisi, cette d&#233;cision ne peut plus &#234;tre modifi&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;table class=&quot;page espace-col troiscol&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Cr&#233;ation&lt;a class=&quot;headeranchor&quot; id=&quot;Cr&#233;ation_1&quot; href=&quot;#Cr&#233;ation_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Les pouvoirs d’&#233;cole suivants remplacent &lt;i&gt;Fl&#233;chette d’acide&lt;/i&gt; et &lt;i&gt;Pas interdimensionnels&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cr&#233;ation d’&#233;quipement (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut cr&#233;er n’importe quel objet pesant moins de 500 g par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;. Cela n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; et l’objet continue d’exister pendant 1 minute avant de dispara&#238;tre, &#224; moins qu’il ne quitte le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;, auquel cas il ne survit qu’un seul &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; avant de dispara&#238;tre. Cr&#233;er un objet qui r&#233;pond &#224; des crit&#232;res pr&#233;cis peut n&#233;cessiter un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (&#224; la discr&#233;tion du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;). L’objet doit &#234;tre compos&#233; de mat&#233;riaux simples comme la pierre, le bois, le verre ou le m&#233;tal et il ne peut pas comporter de parties mobiles. Cette capacit&#233; permet par exemple de cr&#233;er une dague mais pas une fiole de feu gr&#233;geois. Le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Volont&#233; du cr&#233;ateur (Mag).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 8, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Mineure.html&quot; title=&quot;Cr&#233;ation mineure&quot;&gt;cr&#233;ation mineure&lt;/a&gt;&lt;/i&gt; en tant que pouvoir magique. Il ne peut avoir qu’une seule &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Mineure.html&quot; title=&quot;Cr&#233;ation mineure&quot;&gt;cr&#233;ation mineure&lt;/a&gt;&lt;/i&gt; active &#224; la fois : s’il fait appel &#224; ce pouvoir magique une seconde fois, le r&#233;sultat de l’utilisation pr&#233;c&#233;dente dispara&#238;t. Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 12, cette capacit&#233; s’am&#233;liore et imite &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Majeure.html&quot; title=&quot;Cr&#233;ation majeure&quot;&gt;cr&#233;ation majeure&lt;/a&gt;&lt;/i&gt;. Le magicien peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt;.
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;T&#233;l&#233;portation&lt;a class=&quot;headeranchor&quot; id=&quot;T&#233;l&#233;portation_2&quot; href=&quot;#T&#233;l&#233;portation_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Le pouvoir d’&#233;cole suivant remplace &lt;i&gt;Fl&#233;chette d’acide&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;placement (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut se t&#233;l&#233;porter vers un espace proche par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; comme s’il utilisait &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt;&lt;/i&gt;. Ce mouvement ne provoque pas d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;. Il doit &#234;tre capable de voir sa destination et ne peut pas emmener d’autres cr&#233;atures avec lui (&#224; l’exception d’un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#FAMILIER&quot; title=&quot;Le magicien&quot;&gt;familier&lt;/a&gt;). Le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut se d&#233;placer de 1,50 m (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) par tranche de deux &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveaux&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; (minimum 1,50 m (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)). Il peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;
&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Invocation infernale&lt;a class=&quot;headeranchor&quot; id=&quot;Invocation_infernale_3&quot; href=&quot;#Invocation_infernale_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;description&quot;&gt;&lt;b&gt;Source :&lt;/b&gt; Inner Sea Primer (ISP).&lt;/div&gt;&lt;b&gt;Restrictions.&lt;/b&gt; L&#39;alignement du &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; doit &#234;tre Loyal Mauvais, Loyal Neutre, Neutre, ou Neutre Mauvais. De plus, il doit avoir un &lt;a class=&quot;pagelink&quot; href=&quot;Familiers.html&quot; title=&quot;familier&quot;&gt;familier&lt;/a&gt; en tant que pacte magique.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Pouvoirs remplac&#233;s.&lt;/b&gt; Les pouvoirs d’&#233;cole suivants remplacent &lt;i&gt;Fl&#233;chette d’acide&lt;/i&gt; et &lt;i&gt;Pas interdimensionnels&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Connaissances planaires (Ext).&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; gagne un bonus de +3 &#224; tous ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (Plans)&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Prendre le contr&#244;le (Sur).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut tenter de prendre le contr&#244;le d&#39;une cr&#233;ature convoqu&#233;e. il fait un test de lanceur de sort (1d20 + &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt;, DD 10 + &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; de celui qui a convoqu&#233; la cr&#233;ature). S&#39;il conna&#238;t le nom de la cr&#233;ature convoqu&#233;e, il b&#233;n&#233;ficie d&#39;un bonus de +2. Si le test est r&#233;ussi, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; contr&#244;le la cr&#233;ature un nombre de tours &#233;gal &#224; la moiti&#233; de son niveau de magicien comme s&#39;il l&#39;avait convoqu&#233;e. L&#39;invocateur de la cr&#233;ature peut par une action simple tenter de mettre fin &#224; l&#39;effet en faisant un test de lanceur de sort (1d20 + &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt;, DD 10 + &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;). Quand l&#39;effet se termine, la cr&#233;ature retourne sous le contr&#244;le de son invocateur. Au niveau 9, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; peut n&#233;gocier avec les cr&#233;atures convoqu&#233;es comme s&#39;il les avait invoqu&#233;es lui-m&#234;me. Il peut utiliser cette capacit&#233; un nombre de fois par jour &#233;gal &#224; 3 + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Familier diablotin (Ext).&lt;/b&gt; Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 7, le &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; acquiert le don &lt;a class=&quot;pagelink&quot; href=&quot;Familier-Sup&#233;rieur.html&quot; title=&quot;Familier sup&#233;rieur&quot;&gt;Familier sup&#233;rieur&lt;/a&gt; mais doit choisir un &lt;a class=&quot;pagelink&quot; href=&quot;Diablotin.html&quot; title=&quot;Diable, Diablotin&quot;&gt;diablotin&lt;/a&gt; comme familier. Le &lt;a class=&quot;pagelink&quot; href=&quot;Diablotin.html&quot; title=&quot;Diable, Diablotin&quot;&gt;diablotin&lt;/a&gt; remplace le familier actuel du &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;.
&lt;/div&gt;
&lt;/table&gt;
